import { getAgentsEnvironment } from "../../provider/environment";
import generatedComposedNodeSchema from "./composed-node-schema.json";

/**
 * THE schema of the `ComposedView` kit, GENERATED by the backend from its classes (`ComposedViewNodeSchema.php`) —
 * never edited by hand. The committed file holds the types the package's own classes declare; an app adds the node
 * types, widgets, data sources and entity types its classes declare as its part (`AgentsEnvironment.composedNodeSchemaApplicationPart`,
 * generated by the app's backend the same way), and `getComposedNodeSchema()` reads both. The frontend parser, the
 * renderer and the evaluator read the node types, slots, props, size classes and budgets from here, so both sides apply
 * the same contract. `kit/_ComposedViewRenderer.spec.tsx` checks that every node type has a registered component and
 * every component a node type.
 */

export type ComposedNodeCategory = "inline" | "block" | "data" | "media" | "input" | "layout" | "heavy";
export type ComposedSizeClass = "compact" | "regular" | "full";
export type ComposedPropType = "string" | "number" | "boolean" | "array" | "object" | "event";

export interface ComposedNodeSlotSchema {
  name: string;
  acceptsCategories: ComposedNodeCategory[];
  acceptsNodeTypes: string[];
  minChildren: number;
  maxChildren: number | null;
  sizeClass: ComposedSizeClass;
  description: string;
  /** The node prop the slot's size class follows (a Grid's `columns`); absent = the size class is fixed. */
  sizeClassFromProp?: string;
  /** Prop value (as text) → size class; a value not listed keeps `sizeClass`. */
  sizeClassesByPropValue?: Record<string, ComposedSizeClass>;
  /** A heavy node (a map, an embedded widget) may sit in the slot while it is compact. */
  acceptsHeavyWhenCompact?: boolean;
}

export interface ComposedNodePropSchema {
  name: string;
  types: ComposedPropType[];
  isRequired: boolean;
  isBindable: boolean;
  allowedValues: Array<string | number | boolean> | null;
  description: string;
}

/**
 * The type's part in the source rule (`ComposedViewNode::buildSourcingSchemaArray()`): a data node that `needsSource`
 * and holds inline figures in its subtree — written rows in a `rowsProps` prop, a written figure in a `figureProps`
 * prop — needs its `source`, a source on a data node around it, or a node that `namesSources` in the tree.
 */
export interface ComposedNodeSourcingSchema {
  needsSource: boolean;
  namesSources: boolean;
  rowsProps: string[];
  figureProps: string[];
}

export interface ComposedNodeTypeSchema {
  categories: ComposedNodeCategory[];
  providesItemScope: boolean;
  summary: string;
  props: ComposedNodePropSchema[];
  slots: ComposedNodeSlotSchema[];
  /** Absent for a type that takes no part in the source rule. */
  sourcing?: ComposedNodeSourcingSchema;
  /** The prop that lists the node's choices (`ComposedViewNode::OPTIONS_PROP_NAME`); absent without choices. */
  optionsProp?: string;
  /** The prop a node that repeats its children repeats over (`ComposedViewNode::ITEMS_PROP_NAME`). */
  itemsProp?: string;
  /** The node sends the state of the inputs inside it (`Form`); absent otherwise. */
  submitsInputs?: boolean;
}

export interface ComposedViewBudgets {
  maxSourceBytes: number;
  maxNodes: number;
  maxDepth: number;
  maxStateKeys: number;
  maxStateStringLength: number;
  maxComputedExpressions: number;
  maxExpressionSourceLength: number;
  maxExpressionAstNodes: number;
  maxComputedDependencyDepth: number;
  maxOperationsPerUpdate: number;
  maxCollectionItems: number;
  maxAllocatedItemsPerEvaluation: number;
  maxRepeatRows: number;
  maxRenderedNodes: number;
  maxInlineArrayItems: number;
  maxInlineCells: number;
  maxTextLength: number;
  maxActions: number;
  maxInputUpdatesPerSecond: number;
  maxSourceRequestsPerTreePerMinute: number;
}

export interface ComposedDataSourceSchema {
  summary: string;
  /** The client endpoint, method and path with `{param}` placeholders. */
  clientEndpoint: string;
  /** Where the rows sit in the response (`$` or `$.field`). */
  rowsPath: string;
  freshnessSeconds: number;
  params: Array<{ name: string; type: string; isRequired: boolean; description: string }>;
  columns: Array<{ name: string; type: string; description: string }>;
}

export interface ComposedNodeSchema {
  version: number;
  budgets: ComposedViewBudgets;
  categories: ComposedNodeCategory[];
  sizeClasses: ComposedSizeClass[];
  actionTypes: string[];
  bindingKinds: string[];
  findingCodes: string[];
  /** The codes of findings that drop nothing — the block mounts with the code as a note. */
  noteFindingCodes: string[];
  nodeTypes: Record<string, ComposedNodeTypeSchema>;
  embeddableWidgets: Record<string, { sizeClass: ComposedSizeClass }>;
  /** Every registered widget type: a `Widget` node naming one its slot refuses is lifted out of the tree. */
  widgetTypes?: string[];
  dataSources: Record<string, ComposedDataSourceSchema>;
  entityTypes: string[];
}

/** The sections of the schema an app adds for the types its own classes declare; every section is optional. */
export type ComposedNodeSchemaApplicationPart = Partial<
  Pick<ComposedNodeSchema, "nodeTypes" | "embeddableWidgets" | "widgetTypes" | "dataSources" | "entityTypes">
>;

/**
 * The package's committed schema, typed: its budgets and rules and the types the package itself declares. A reader of
 * types an app may add (node types, widgets, data sources, entity types) reads `getComposedNodeSchema()`.
 */
export const composedNodeSchema = generatedComposedNodeSchema as unknown as ComposedNodeSchema;

/** Byte order of the type names, as the backend sorts them. */
const compareTypeNames = (first: string, second: string): number => (first < second ? -1 : first > second ? 1 : 0);

const mergeSortedByTypeName = <Entry>(
  packageEntries: Record<string, Entry> | undefined,
  applicationEntries: Record<string, Entry> | undefined,
): Record<string, Entry> =>
  Object.fromEntries(
    Object.entries({ ...packageEntries, ...applicationEntries }).sort(([firstType], [secondType]) =>
      compareTypeNames(firstType, secondType),
    ),
  );

const mergeTypeNames = (packageTypeNames: string[] | undefined, applicationTypeNames: string[] | undefined): string[] =>
  [...new Set([...(packageTypeNames ?? []), ...(applicationTypeNames ?? [])])].sort(compareTypeNames);

/** A schema with an app's part added: every section holds both sides' types, sorted by type name. */
export const addComposedNodeSchemaApplicationPart = (
  schema: ComposedNodeSchema,
  applicationPart: ComposedNodeSchemaApplicationPart,
): ComposedNodeSchema => ({
  ...schema,
  nodeTypes: mergeSortedByTypeName(schema.nodeTypes, applicationPart.nodeTypes),
  embeddableWidgets: mergeSortedByTypeName(schema.embeddableWidgets, applicationPart.embeddableWidgets),
  widgetTypes: mergeTypeNames(schema.widgetTypes, applicationPart.widgetTypes),
  dataSources: mergeSortedByTypeName(schema.dataSources, applicationPart.dataSources),
  entityTypes: mergeTypeNames(schema.entityTypes, applicationPart.entityTypes),
});

let schemaWithApplicationPart:
  | { applicationPart: ComposedNodeSchemaApplicationPart; schema: ComposedNodeSchema }
  | undefined;

/**
 * The schema the readers apply: the package's schema with the part the app declares
 * (`AgentsEnvironment.composedNodeSchemaApplicationPart`); the package's schema alone when the app declares none.
 * Read at call time — an app installs its environment after this module is loaded. The same object while the part is.
 */
export const getComposedNodeSchema = (): ComposedNodeSchema => {
  const applicationPart = getAgentsEnvironment().composedNodeSchemaApplicationPart;
  if (!applicationPart) return composedNodeSchema;
  if (schemaWithApplicationPart?.applicationPart !== applicationPart) {
    schemaWithApplicationPart = {
      applicationPart,
      schema: addComposedNodeSchemaApplicationPart(composedNodeSchema, applicationPart),
    };
  }
  return schemaWithApplicationPart.schema;
};

/**
 * The slot of one node — `ComposedViewNodeSlot::buildForNodeProps()`: its size class read from the node's
 * `sizeClassFromProp` (a Grid with `columns: 3` gives compact cells); the declaration itself otherwise.
 */
export const resolveComposedSlotForNodeProps = (
  slot: ComposedNodeSlotSchema,
  nodeProps: Record<string, unknown>,
): ComposedNodeSlotSchema => {
  if (!slot.sizeClassFromProp || !slot.sizeClassesByPropValue) return slot;
  const propValue = Object.prototype.hasOwnProperty.call(nodeProps, slot.sizeClassFromProp)
    ? nodeProps[slot.sizeClassFromProp]
    : undefined;
  if (typeof propValue !== "number" && typeof propValue !== "string") return slot;
  const propValueKey = String(propValue);
  const sizeClassOfPropValue = Object.prototype.hasOwnProperty.call(slot.sizeClassesByPropValue, propValueKey)
    ? slot.sizeClassesByPropValue[propValueKey]
    : undefined;
  return sizeClassOfPropValue === undefined || sizeClassOfPropValue === slot.sizeClass
    ? slot
    : { ...slot, sizeClass: sizeClassOfPropValue };
};

/** Whether a size class fits a slot's size class (compact ≤ regular ≤ full). */
export const sizeClassFitsSlot = (sizeClass: ComposedSizeClass, slotSizeClass: ComposedSizeClass): boolean => {
  const order: ComposedSizeClass[] = ["compact", "regular", "full"];
  return order.indexOf(sizeClass) !== -1 && order.indexOf(sizeClass) <= order.indexOf(slotSizeClass);
};
